-- UNSUPPORTED: malpractice / professional-liability claims, settlements or legal payouts (no malpractice, liability, litigation, settlement, incident, legal or risk-management stream; medical and pharmacy claims are payer adjudications of care). Diagnostic returns prerequisite_available = 0 when no such stream has been received.
SELECT CASE WHEN EXISTS (SELECT 1 FROM records WHERE stream LIKE '%malpractice%' OR stream LIKE '%liabilit%' OR stream LIKE '%litigation%' OR stream LIKE '%settlement%' OR stream LIKE '%incident%' OR stream LIKE '%legal%' OR stream LIKE '%risk_management%' OR stream LIKE '%lawsuit%') THEN 1 ELSE 0 END AS prerequisite_available;
